import { AlignMethod, layoutChain, makeAlign } from "@kvisaz/phaser-sugar";
import { SceneEvents } from "../../../common";
import { GameServiceProvider } from "../../../services";
import { assetsViewsAutoAssets } from "../assets-views-assets";
import { createTextView, makeContainerInteractive, setLeftTop } from "../utils";
import { assetsViewsTexts } from "./assets-views.text";
import { ButtonEvents } from "../addButtonViewInteractivity";

const OPTION_GAP = 4;
const ROW_GAP = 22;
const BRIGHTNESS_VALUES: number[] = [10, 25, 50, 75, 100] as const;

interface ICreateBgOpacityControlProps {
  scene: Phaser.Scene;
}

interface IBgOpacityOptionProps {
  scene: Phaser.Scene;
  value: number;
  isSelected: boolean;
  onSelect: (option: BgOpacityOption) => void;
}

interface IBgOpacityControlEvents {
  setBgOpacity: { opacity: number };
}

export function createBgOpacityControl(props: ICreateBgOpacityControlProps): Phaser.GameObjects.Container {
  return new BgOpacityControl(props);
}

export class BgOpacityControl extends Phaser.GameObjects.Container {
  private readonly options: BgOpacityOption[];
  private readonly sceneEvents: SceneEvents<IBgOpacityControlEvents>;

  constructor(private readonly props: ICreateBgOpacityControlProps) {
    super(props.scene, 0, 0);

    this.sceneEvents = new SceneEvents<IBgOpacityControlEvents>({ scene: props.scene, autoUnSub: this });

    const gameService = GameServiceProvider.get();
    const currentValue = getPercentValue(gameService.getPlayerData().gameBgUrlOverlayOpacity);
    const title = createTextView(props.scene, assetsViewsTexts["text.bgOpacity.title"]);
    setLeftTop(title, 0, 0);

    this.options = BRIGHTNESS_VALUES.map(
      (value) =>
        new BgOpacityOption({
          scene: props.scene,
          value,
          isSelected: value === currentValue,
          onSelect: (option) => this.setSelectedOption(option),
        }),
    );

    const row = layoutChain({
      children: [title, ...this.options],
      alignToNext: AlignMethod.RIGHT_TO,
      nextOffsetX: ROW_GAP,
      alignToAnchor: AlignMethod.CENTER_Y,
    });

    this.add([title, ...this.options]);
    this.setSize(row.getBounds().width, row.getBounds().height);
  }

  private setSelectedOption(selectedOption: BgOpacityOption): void {
    this.options.forEach((option) => option.setSelected(option === selectedOption));

    const opacity = selectedOption.value / 100;

    /** Контрол отдает намерение, а BgAssetManager сохраняет opacity и пересобирает фон. **/
    this.sceneEvents.emit("setBgOpacity", { opacity });
  }
}

export class BgOpacityOption extends Phaser.GameObjects.Container {
  private readonly bg: Phaser.GameObjects.Image;
  private readonly check: Phaser.GameObjects.Image;
  private isSelected = false;

  constructor(private readonly props: IBgOpacityOptionProps) {
    super(props.scene, 0, 0);

    const label = createValueLabel(props.scene, props.value);
    this.bg = createCheckboxBg(props.scene);
    this.check = createCheckboxCheck(props.scene);

    layoutChain({
      children: [label, this.bg],
      alignToNext: AlignMethod.RIGHT_TO,
      nextOffsetX: OPTION_GAP,
      alignToAnchor: AlignMethod.CENTER_Y,
    });

    makeAlign((align) => align.anchor(this.bg).center(this.check));

    this.add([label, this.bg, this.check]);
    this.setSelected(props.isSelected);
    makeContainerInteractive(this);
    this.on(Phaser.Input.Events.POINTER_OVER, () => this.handleHover());
    this.on(Phaser.Input.Events.POINTER_DOWN, () => this.handleClick());
  }

  get value(): number {
    return this.props.value;
  }

  setSelected(isSelected: boolean): void {
    this.isSelected = isSelected;
    this.bg.setVisible(true);
    this.check.setVisible(isSelected);
  }

  private handleHover(): void {
    if (this.isSelected) {
      return;
    }

    this.scene.events.emit(ButtonEvents.onHover, { gameObjectName: this.name });
  }

  private handleClick(): void {
    if (this.isSelected) {
      return;
    }

    this.scene.events.emit(ButtonEvents.onClick, { gameObjectName: this.name });
    this.props.onSelect(this);
  }
}

function getPercentValue(opacity: number): number {
  const percent = Math.round(opacity * 100);
  let closestValue = BRIGHTNESS_VALUES[0];

  BRIGHTNESS_VALUES.forEach((value) => {
    if (Math.abs(value - percent) < Math.abs(closestValue - percent)) {
      closestValue = value;
    }
  });

  return closestValue;
}

function createValueLabel(scene: Phaser.Scene, value: number): Phaser.GameObjects.Text {
  const label = createTextView(scene, assetsViewsTexts["text.bgOpacity.title"], {
    text: String(value)
  });
  label.name = `text.bgBrightness.value.${value}`;
  setLeftTop(label, 0, 0);

  return label;
}

function createCheckboxBg(scene: Phaser.Scene): Phaser.GameObjects.Image {
  const asset = assetsViewsAutoAssets.bgopacityCheckmarkBg;
  const bg = new Phaser.GameObjects.Image(scene, 0, 0, asset.url, asset.frameName);
  bg.name = asset.name;
  setLeftTop(bg, 0, 0);

  return bg;
}

function createCheckboxCheck(scene: Phaser.Scene): Phaser.GameObjects.Image {
  const asset = assetsViewsAutoAssets.iconCheckmark40;
  const check = new Phaser.GameObjects.Image(scene, 0, 0, asset.url, asset.frameName);
  check.name = asset.name;
  setLeftTop(check, 0, 0);

  return check;
}
