import {Align, cssColorToInt} from "@kvisaz/phaser-sugar";
import {ViewElementBuilder} from "../../assets";
import {SpiderWrap} from "./components/SpiderWrap";
import {SpiderCollectButton, SpiderControls, SpiderInfoUi} from "./components/spider-ui";
import {SpiderGameSceneViewLogic} from "./logic";
import {defaultSpiderConfig, getSceneBounds, safeArray, SceneEvents} from "../../common";
import {GameServiceProvider} from "../../services";
import {getSpiderCardBackButton, getSpiderCardThemeButton,} from "../shared";
import {SpiderGameScenes} from "../scenes";
import {SceneLayout, ScenePlaceType} from "../shared/layout";
import {isGameShopAvailable} from "../shared/shopScene/getAvailableGameShopItems";
import {IGameEvents} from '../events';
import {MoneyCounter} from "../auto_generated/tuned";

interface IProps {
    scene: Phaser.Scene;
}

export class SpiderGameSceneView {
    private readonly unSubs: Array<() => void> = [];
    private readonly gameLogic: SpiderGameSceneViewLogic;

    constructor(private readonly props: IProps) {
        const {scene} = props;
        const sceneEvents = new SceneEvents<IGameEvents>({scene});

        const align = new Align();

        const builder = new ViewElementBuilder(scene);
        const sceneLayout = new SceneLayout({scene});
        /** Счетчик золота живет вместе с игровой сценой и чистит подписку при destroy. **/
        const moneyCounter = new MoneyCounter(scene);
        Align.setLeftTop(moneyCounter, 158, 20);
        this.unSubs.push(() => moneyCounter.destroy());

        const playerData = GameServiceProvider.get().getPlayerData();
        const spiderConfig = {
            ...defaultSpiderConfig,
            suitsMode: playerData.spiderSuitsMode,
        };
        this.gameLogic = new SpiderGameSceneViewLogic({scene, spiderConfig});
        this.unSubs.push(() => this.gameLogic.destroy());
        this.unSubs.push(() => sceneEvents.unSubscribeAll());


        const backButton = builder.buttonBack(() => {
            sceneEvents.emit("onBackButtonClick");
        });
        this.unSubs.push(() => backButton.destroy());

        const infoUi = new SpiderInfoUi({
            scene,
            gameState: this.gameLogic.observable(),
        });
        this.unSubs.push(() => infoUi.destroy());

        const cardThemeButton = getSpiderCardThemeButton({scene});
        this.unSubs.push(() => cardThemeButton.destroy());

        const backThemeButton = getSpiderCardBackButton({scene});
        this.unSubs.push(() => backThemeButton.destroy());

        const shopButton = isGameShopAvailable()
            ? builder.buttonShop(() => {
                sceneEvents.emit("onShopButtonClick");
            })
            : undefined;
        if (shopButton) {
            this.unSubs.push(() => shopButton.destroy());
        }

        const controls = new SpiderControls({
            scene,
            gameState: this.gameLogic.observable(),
        });
        this.unSubs.push(() => controls.destroy());

        /** TOP_CENTER sidebar **/
        sceneLayout.sidebar({
            children: [cardThemeButton, infoUi, backThemeButton],
            place: ScenePlaceType.TOP_CENTER,
        });

        /** TOP_LEFT vertical sidebar **/
        align.anchorSceneScreen(scene).leftIn(backButton, 8).topIn(backButton, 8);

        if (shopButton) {
            align.anchor(backButton).bottomTo(shopButton, 43).centerX(shopButton);
        }

        align.anchor(backButton).bottomTo(controls, 210).leftIn(controls, 10);

        const collectButton = new SpiderCollectButton({
            scene,
            gameState: this.gameLogic.observable(),
        });
        align.anchorSceneScreen(scene).topIn(collectButton, 62).leftIn(collectButton, 760);
        this.unSubs.push(() => collectButton.destroy());

        /** TOP_RIGHT sidebar **/
        sceneLayout.sidebar({
            children: safeArray([]),
            place: ScenePlaceType.TOP_RIGHT,
        });

        const sceneBounds = getSceneBounds(scene);
        const spiderLayoutZoneColor = cssColorToInt("#ded000");
        const spiderLayoutZone = new Phaser.GameObjects.Rectangle(
            scene,
            0,
            0,
            sceneBounds.width,
            sceneBounds.height / 2,
            spiderLayoutZoneColor,
        );
        align.anchorSceneScreen(scene).topIn(spiderLayoutZone, 135).rightIn(spiderLayoutZone, -48);
        // scene.add.existing(spiderLayoutZone);

        const spiderWrap = new SpiderWrap({
            scene,
            layoutZone: spiderLayoutZone,
        });
        this.unSubs.push(() => spiderWrap.destroy());

        this.unSubs.push(
            sceneEvents.on("uiModeSelectClick", () => {
                scene.scene.start(SpiderGameScenes.SpiderStart);
            }),
        );

        this.gameLogic.startNewGame({shuffleDeck: true});
    }

    destroy() {
        this.unSubs.forEach((u) => u());
    }
}
