import {GamePlayerData} from './types';

export const mergePlayerData = (
    target: GamePlayerData,
    options: Partial<GamePlayerData> = {},
): GamePlayerData => {
    /** GamePlayerData теперь плоский, поэтому частичное сохранение мержится без ручной сборки секций. **/
    return {
        ...target,
        ...options,
    };
};
