import {makeAlign} from "@kvisaz/phaser-sugar";
import {GameServiceProvider} from "../../../services";
import {viewMoneyCounterData} from "../assets-views.view";

/**
 * Счетчик золота игрока.
 *
 * Использует автогенерированный `viewMoneyCounterData` только как источник ассетов,
 * размеров и текстового стиля. Внутренняя верстка остается tuned и строится
 * через `makeAlign`, чтобы не зависеть от координат автогенерации.
 **/
export class MoneyCounter extends Phaser.GameObjects.Container {
    private readonly unSub: () => void;
    private readonly text: Phaser.GameObjects.Text;

    constructor(scene: Phaser.Scene) {
        super(scene, 0, 0);

        const bg = this.createBackground(scene);
        const coin = this.createCoin(scene);
        this.text = this.createText(scene);

        /** Ключевая ручная верстка счетчика: фон -> монетка -> текст. **/
        makeAlign((align) => {
            align.anchor(bg).leftIn(coin, 3).centerY(coin);
            align.anchor(coin).rightTo(this.text, 5).centerY(this.text);
        });

        this.add([bg, coin, this.text]);
        this.setSize(viewMoneyCounterData.width, viewMoneyCounterData.height);

        const playerData = GameServiceProvider.get().playerDataObservable();
        this.setGold(playerData.getState().gold);
        this.unSub = playerData.on((data) => this.setGold(data.gold), "gold");

        scene.add.existing(this);
    }

    destroy(fromScene?: boolean): void {
        this.unSub();
        super.destroy(fromScene);
    }

    private createBackground(scene: Phaser.Scene): Phaser.GameObjects.NineSlice {
        const bgData = viewMoneyCounterData.children["moneyCounter.nine.23"];
        const padding = bgData.asset.ninePadding ?? 23;

        const bg = scene.add.nineslice(
            0,
            0,
            bgData.asset.url,
            bgData.asset.frameName,
            bgData.width,
            bgData.height,
            padding,
            padding,
            padding,
            padding,
        );
        bg.name = bgData.asset.name;

        return bg;
    }

    private createCoin(scene: Phaser.Scene): Phaser.GameObjects.Image {
        const coinData = viewMoneyCounterData.children.coin_43;
        const coin = scene.add.image(0, 0, coinData.asset.url, coinData.asset.frameName);
        coin.name = coinData.asset.name;
        coin.setDisplaySize(coinData.width, coinData.height);

        return coin;
    }

    private createText(scene: Phaser.Scene): Phaser.GameObjects.Text {
        const textData = viewMoneyCounterData.children.textMoneyCounter;
        const text = scene.add.text(0, 0, "", textData.text.style);
        text.name = textData.text.name ?? "";
        text.setFixedSize(textData.width, textData.height);

        return text;
    }

    private setGold(gold: number): void {
        this.text.setText(String(gold));
    }
}
