import { AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { createGO, Observable, SceneEvents } from "../../../../common";
import { ViewElementBuilder } from "../../../../assets";
import { ISpiderExposedState } from "../../../../common/games/spider";
import { ConsumableType, getPlayerConsumables } from "../../../../logic";
import { GameServiceProvider } from "../../../../services";
import { ISpiderUiEvents } from "./events";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<ISpiderExposedState>;
}

export class SpiderControls extends Phaser.GameObjects.Container {
  private readonly unSubs: Array<() => void> = [];
  private readonly sceneEvents: SceneEvents<ISpiderUiEvents>;

  constructor(private readonly props: IProps) {
    super(props.scene);
    this.sceneEvents = new SceneEvents<ISpiderUiEvents>({ scene: props.scene, autoUnSub: this });
    const buttons = this.createButtons();

    layoutChain({
      children: buttons,
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 16,
      alignToAnchor: AlignMethod.LEFT_IN,
    });

    this.add(buttons);
    this.scene.add.existing(this);
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  private createButtons() {
    const { scene, gameState } = this.props;
    const { sceneEvents } = this;
    const builder = new ViewElementBuilder(scene);

    const newGameButton = createGO(() => builder.buttonNewGame(() => sceneEvents.emit("uiNewGameClick")));
    const replayButton = createGO(() => builder.buttonReplayGame(() => sceneEvents.emit("uiReplayClick")));

    const undoButton = createGO(
      () =>
        builder.buttonUndo(() => sceneEvents.emit("spiderUndoRequest")),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) => button.enable(state.isUndoPossible);
          this.unSubs.push(gameState.on(applyState, ["isUndoPossible", "step"]));
          applyState(gameState.getState());
        },
      },
    );

    const hintButton = createGO(
      () =>
        builder.buttonHint(() => sceneEvents.emit("spiderHintRequest")),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) =>
            button.enable(state.step === "idle" && state.isHintPossible);
          this.unSubs.push(gameState.on(applyState, ["step", "isHintPossible"]));
          applyState(gameState.getState());
        },
      },
    );

    const magicButton = createGO(
      () =>
        builder.buttonMagic(() => sceneEvents.emit("spiderMagicRequest")),
      {
        use: (button) => {
          const applyState = (state: ISpiderExposedState) => button.enable(state.isMagicPossible);
          this.unSubs.push(gameState.on(applyState, "isMagicPossible"));
          applyState(gameState.getState());
        },
      },
    );

    const syncConsumables = () => {
      const consumables = getPlayerConsumables(GameServiceProvider.get().getPlayerData());
      undoButton.setAmount(consumables[ConsumableType.UNDO]);
      hintButton.setAmount(consumables[ConsumableType.HINT]);
      magicButton.setAmount(consumables[ConsumableType.MAGIC]);
    };

    syncConsumables();
    this.unSubs.push(sceneEvents.on("gameShopPurchaseApplied", syncConsumables));
    this.unSubs.push(sceneEvents.on("gameConsumablesUpdated", syncConsumables));

    return [newGameButton, replayButton, undoButton, hintButton, magicButton];
  }
}
