import {Align} from "@kvisaz/phaser-sugar";
import {SceneEvents} from "../../../common";
import {themeConfig} from "../../../config.themes";
import {ButtonEvents} from "../../auto_generated/addButtonViewInteractivity";
import {
    MoneyCounter,
    createViewBgShop,
    createViewCardBackShop,
    createViewCardShop,
    createViewStyleEntrance,
} from "../../auto_generated/tuned";
import {IGameEvents} from "../../events";
import {BackgroundShopController} from "./background-shop";
import {CardBackShopController} from "./card-back-shop";
import {CardThemeController} from "./controllers";
import type {ThemeShopScreen} from "./types";

interface IProps {
    scene: Phaser.Scene;
    close: () => void;
}

/** Flow остается оркестратором: держит текущий экран, back-навигацию и замену view. **/
export class ThemeShopDialogFlow {
    readonly view: Phaser.GameObjects.Container;

    private readonly sceneEvents: SceneEvents<IGameEvents>;
    private readonly backgroundShopController: BackgroundShopController;
    private readonly cardBackShopController: CardBackShopController;
    private readonly cardThemeController: CardThemeController;
    private readonly moneyCounter: MoneyCounter;
    private currentView?: Phaser.GameObjects.Container;
    private currentScreen: ThemeShopScreen = "entrance";

    constructor(private readonly props: IProps) {
        this.view = props.scene.add.container(0, 0);
        this.sceneEvents = new SceneEvents<IGameEvents>({scene: props.scene, autoUnSub: this.view});
        this.backgroundShopController = new BackgroundShopController({scene: props.scene});
        this.cardBackShopController = new CardBackShopController({scene: props.scene});
        this.cardThemeController = new CardThemeController({scene: props.scene});
        this.sceneEvents.on("buySceneBg", ({id}) => {
            this.buySceneBg(id);
        });
        this.sceneEvents.on("setCardBack", ({cardBackAssetName}) => {
            this.cardBackShopController.selectCardBack(cardBackAssetName);
        });
        this.sceneEvents.on("buyCardBack", ({id}) => {
            this.buyCardBack(id);
        });
        props.scene.events.on(ButtonEvents.onClick, this.onButtonClick);
        this.view.once(Phaser.GameObjects.Events.DESTROY, () => this.destroy());
        this.showEntrance();
        /** Счетчик живет в корне flow и не пересоздается при смене экранов магазина. **/
        this.moneyCounter = new MoneyCounter(props.scene);
        Align.setLeftTop(this.moneyCounter, 158, 20);
    }

    destroy(): void {
        this.backgroundShopController.destroy();
        this.cardBackShopController.destroy();
        this.cardThemeController.destroy();
        this.sceneEvents.unSubscribeAll();
        this.props.scene.events.off(ButtonEvents.onClick, this.onButtonClick);
        this.currentView?.destroy();
        this.moneyCounter.destroy();
        this.currentView = undefined;
    }

    private showEntrance(): void {
        this.replaceView(createViewStyleEntrance(this.props.scene), "entrance");
    }

    private showBgShop(): void {
        this.replaceView(
            createViewBgShop({
                scene: this.props.scene,
                backgrounds: themeConfig.backgrounds,
            }),
            "bg",
        );
    }

    private showCardShop(): void {
        this.replaceView(
            createViewCardShop({
                scene: this.props.scene,
                selectedTheme: this.cardThemeController.getSelectedTheme(),
                onSelectTheme: (theme) => {
                    this.cardThemeController.selectCardsTheme(theme);
                    this.showCardShop();
                },
            }),
            "cards",
        );
    }

    private showCardBackShop(): void {
        this.replaceView(
            createViewCardBackShop({
                scene: this.props.scene,
                cardBacks: themeConfig.cardBacks,
            }),
            "cardBacks",
        );
    }

    private replaceView(nextView: Phaser.GameObjects.Container, screen: ThemeShopScreen): void {
        /** Единственная ответственность flow: заменить текущий экран и запомнить маршрут для back. **/
        this.currentView?.destroy();
        this.currentView = nextView;
        this.currentScreen = screen;
        this.view.add(nextView);
    }

    private onButtonClick = ({gameObjectName}: { gameObjectName: string }) => {
        if (gameObjectName === "buttonBack") {
            this.onBackButtonClick();
            return;
        }

        if (gameObjectName === "button.StyleEntranceWallpapers") {
            this.showBgShop();
            return;
        }

        if (gameObjectName === "button.StyleEntranceCards") {
            this.showCardShop();
            return;
        }

        if (gameObjectName === "button.StyleEntranceCardBacks") {
            this.showCardBackShop();
        }
    };

    private onBackButtonClick(): void {
        if (this.currentScreen === "entrance") {
            this.props.close();
            return;
        }

        this.showEntrance();
    }

    private buySceneBg(backgroundId: string): void {
        if (this.backgroundShopController.buyBackgroundById(backgroundId)) {
            this.showBgShop();
        }
    }

    private buyCardBack(cardBackId: string): void {
        if (this.cardBackShopController.buyCardBackById(cardBackId)) {
            this.showCardBackShop();
        }
    }
}
