import { ILootDto, LootItemType } from "../types";
import {ConsumableAmounts, ConsumableType} from '../shop';

const lootTypes: LootItemType[] = [
  ConsumableType.UNDO,
  ConsumableType.HINT,
  ConsumableType.MAGIC,
];

export function mapConsumableRecordToLootDto(rewards: ConsumableAmounts): ILootDto[] {
  const validLootTypes = new Set<string>(lootTypes);

  return Object.entries(rewards)
    .filter(([key]) => validLootTypes.has(key))
    .map(([key, amount]) => ({ type: key as LootItemType, amount }))
    .filter((dto) => dto.amount > 0);
}
