export function createViewGameOver(scene: Phaser.Scene): Phaser.GameObjects.Container {
    const view = createContainerFromViewData(scene, viewGameOverData);

    const uiDialogBgLightNine40 = createAssetChild(scene, viewGameOverData.children['ui.dialog.bg.light.nine.40']);
    setLeftTop(
        uiDialogBgLightNine40,
        viewGameOverData.children['ui.dialog.bg.light.nine.40'].x - viewGameOverData.width / 2,
        viewGameOverData.children['ui.dialog.bg.light.nine.40'].y - viewGameOverData.height / 2,
    );
    view.add(uiDialogBgLightNine40);

    // ------- тексты -----


    const textGameOverTitle = createTextChild(scene, viewGameOverData.children['text.gameOver.title']);
    setLeftTop(
        textGameOverTitle,
        viewGameOverData.children['text.gameOver.title'].x - viewGameOverData.width / 2,
        viewGameOverData.children['text.gameOver.title'].y - viewGameOverData.height / 2,
    );
    centerX(uiDialogBgLightNine40, textGameOverTitle);
    view.add(textGameOverTitle);

    const textGameOverScore = createTextChild(scene, viewGameOverData.children['text.gameOver.score']);
    setLeftTop(
        textGameOverScore,
        viewGameOverData.children['text.gameOver.score'].x - viewGameOverData.width / 2,
        viewGameOverData.children['text.gameOver.score'].y - viewGameOverData.height / 2,
    );
    centerX(uiDialogBgLightNine40, textGameOverScore);
    view.add(textGameOverScore);

    const viewGameOverMoney = buildViewGameOverMoney(scene);

    setLeftTop(
        viewGameOverMoney,
        viewGameOverData.children['view.GameOver.Money'].x - viewGameOverData.width / 2,
        viewGameOverData.children['view.GameOver.Money'].y - viewGameOverData.height / 2,
    );
    view.add(viewGameOverMoney);

    makeAlign(align => {
        align.anchor(uiDialogBgLightNine40).centerX(textGameOverTitle);
        align.anchor(uiDialogBgLightNine40).centerX(textGameOverScore);
        align.anchor(uiDialogBgLightNine40).centerX(viewGameOverMoney);
    })


    // -------  кнопки -----
    const buttonGameOverRestart = buildButtonGameOverRestart(scene);
    setLeftTop(
        buttonGameOverRestart,
        viewGameOverData.children['button.GameOverRestart'].x - viewGameOverData.width / 2,
        viewGameOverData.children['button.GameOverRestart'].y - viewGameOverData.height / 2,
    );
    view.add(buttonGameOverRestart);

    const buttonGameOverMode = buildButtonGameOverMode(scene);
    setLeftTop(
        buttonGameOverMode,
        viewGameOverData.children['button.GameOverMode'].x - viewGameOverData.width / 2,
        viewGameOverData.children['button.GameOverMode'].y - viewGameOverData.height / 2,
    );
    view.add(buttonGameOverMode);

    // -------  коты -----
    const startHeroRedCat = createAssetChild(scene, viewGameOverData.children['start.hero.red.cat']);
    setLeftTop(
        startHeroRedCat,
        viewGameOverData.children['start.hero.red.cat'].x - viewGameOverData.width / 2,
        viewGameOverData.children['start.hero.red.cat'].y - viewGameOverData.height / 2,
    );
    view.add(startHeroRedCat);

    const startHeroBlackCat = createAssetChild(scene, viewGameOverData.children['start.hero.black.cat']);
    setLeftTop(
        startHeroBlackCat,
        viewGameOverData.children['start.hero.black.cat'].x - viewGameOverData.width / 2,
        viewGameOverData.children['start.hero.black.cat'].y - viewGameOverData.height / 2,
    );
    view.add(startHeroBlackCat);

    // ---

    return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildButtonGameOverRestart(scene: Phaser.Scene): Phaser.GameObjects.Container {
    const data = viewGameOverData.children['button.GameOverRestart'];
    const view = createContainerFromViewData(scene, data);

    const uiButtonGreenHeight82Nine36 = createAssetChild(scene, data.children['ui.button.green.height82.nine.36']);
    setLeftTop(
        uiButtonGreenHeight82Nine36,
        data.children['ui.button.green.height82.nine.36'].x - data.width / 2,
        data.children['ui.button.green.height82.nine.36'].y - data.height / 2,
    );
    view.add(uiButtonGreenHeight82Nine36);

    const textBtGameOverRestart = createTextChild(scene, data.children.textBtGameOverRestart);
    setLeftTop(
        textBtGameOverRestart,
        data.children.textBtGameOverRestart.x - data.width / 2,
        data.children.textBtGameOverRestart.y - data.height / 2,
    );
    view.add(textBtGameOverRestart);

    centerX(uiButtonGreenHeight82Nine36, textBtGameOverRestart);
    return view;
}

