/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildViewGameOverMoney(scene: Phaser.Scene): Phaser.GameObjects.Container {
    const data = viewGameOverData.children['view.GameOver.Money'];
    const view = createContainerFromViewData(scene, data);

    const textGameOverMoney = createTextChild(scene, data.children['text.GameOver.Money']);
    const coin = createAssetChild(scene, data.children.coin);

    makeAlign(align => {
        align.anchor(textGameOverMoney).centerY(coin).rightTo(coin, 5)
    })
    view.add([textGameOverMoney, coin]);
    return view;
}
