import { GameServicePlayerData } from "../types";
import { getUrlParam, isAllowedHost } from "../../../common";

export function getCheatPlayerData(): Partial<GameServicePlayerData> | undefined {
  if(!isAllowedHost(["localhost", "kvisaz.github.io"])) return;

  return mergeCheatData([
    getMegaBonusData('iddqd'),
    getZeroBonusData('zero'),
    getGoldBonusData('gold'),
  ]);
}


function getMegaBonusData(cheat:string): Partial<GameServicePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumableUndo: 999,
    consumableHint: 999,
    consumableMagic: 999,
  };
}

function getZeroBonusData(cheat:string): Partial<GameServicePlayerData> | undefined {
  const isCheatEnabled = getUrlParam(cheat);

  if (!isCheatEnabled) return;

  return {
    consumableUndo: 0,
    consumableHint: 0,
    consumableMagic: 0,
  };
}

function getGoldBonusData(cheat: string): Partial<GameServicePlayerData> | undefined {
  const goldParam = getUrlParam(cheat);

  if (goldParam == null) return;

  const gold = Number(goldParam || 9999);
  if (!Number.isFinite(gold)) return;

  return {
    gold,
  };
}

function mergeCheatData(
  items: Array<Partial<GameServicePlayerData> | undefined>,
): Partial<GameServicePlayerData> | undefined {
  let hasCheat = false;
  const result: Partial<GameServicePlayerData> = {};

  items.forEach((item) => {
    if (item == null) return;
    hasCheat = true;

    /** Flat GamePlayerData позволяет объединять читы простым shallow merge. **/
    Object.assign(result, item);
  });

  return hasCheat ? result : undefined;
}
