import {SceneEvents} from "../../../../common";
import {themeConfig, type ThemeBackground} from "../../../../config.themes";
import {GameServiceProvider} from "../../../../services";
import {IGameEvents} from "../../../events";

interface IProps {
    scene: Phaser.Scene;
}

export class BackgroundShopController {
    private readonly events: SceneEvents<IGameEvents>;

    constructor(private readonly props: IProps) {
        this.events = new SceneEvents<IGameEvents>({scene: props.scene});
    }

    destroy(): void {
        this.events.unSubscribeAll();
    }

    selectBackground(background: ThemeBackground): void {
        this.events.emit("setSceneBg", {
            url: background.imageUrl.url,
        });
    }

    buyBackground(background: ThemeBackground): boolean {
        const gameService = GameServiceProvider.get();
        const playerData = gameService.getPlayerData();
        const boughtBackgroundIds = playerData.boughtBackgroundIds;

        if (background.price <= 0 || boughtBackgroundIds.indexOf(background.id) >= 0) {
            this.selectBackground(background);
            return true;
        }

        if (playerData.gold < background.price) {
            console.warn("not enough gold for background", background.id);
            return false;
        }

        gameService.setPlayerData({
            gold: playerData.gold - background.price,
            boughtBackgroundIds: [...boughtBackgroundIds, background.id],
        });

        this.selectBackground(background);

        return true;
    }

    buyBackgroundById(backgroundId: string): boolean {
        const background = themeConfig.backgrounds.find((item) => item.id === backgroundId);
        if (background == null) {
            console.warn("unknown background", backgroundId);
            return false;
        }

        return this.buyBackground(background);
    }
}
