import {ViewElementBuilder} from "../../../../assets";
import {ConfirmDialog} from "../ConfirmDialog";
import {IConfirmDialogRequest, IConfirmResult} from "../types";

interface IConfirmBackButtonProps {
    scene: Phaser.Scene;
    onClick: () => void;
    confirmRequest?: IConfirmDialogRequest;
}

const defaultConfirmRequest: IConfirmDialogRequest = {
    titleKey: "backDialog.Title",
    infoKey: "backDialog.Info",
    theme: "danger",
};

export class ConfirmBackButton extends Phaser.GameObjects.Container {
    private readonly confirmRequest: IConfirmDialogRequest;
    private confirmDialog?: ConfirmDialog;

    constructor(private readonly props: IConfirmBackButtonProps) {
        super(props.scene);
        this.confirmRequest = props.confirmRequest ?? defaultConfirmRequest;

        const builder = new ViewElementBuilder(props.scene);
        const button = builder.buttonBack(() => this.onBackClick());

        this.add(button);
        props.scene.add.existing(this);
    }

    destroy(fromScene?: boolean): void {
        this.confirmDialog?.destroy();
        this.confirmDialog = undefined;
        super.destroy(fromScene);
    }

    private onBackClick(): void {
        this.confirmDialog ??= new ConfirmDialog({scene: this.scene});
        this.confirmDialog.confirm(this.confirmRequest, (result) => this.onConfirmResult(result));
    }

    private onConfirmResult(result: IConfirmResult): void {
        if (!result.confirmed) {
            return;
        }

        this.props.onClick();
    }
}
