import {BgAssetManager, SoundPlayerFeature} from "../shared";
import {SpiderGameScenes} from "../scenes";
import {SpiderStartView} from "./SpiderStartView";
import {SpiderSelectStyleDialogManager, SpiderSettingsDialogManager} from '../dialog';
import {addButtonInteractivity, testButtonViewInteractivity} from '../auto_generated/addButtonViewInteractivity';
import {addGeneratedButtonSounds} from '../auto_generated/tuned/utils.tuned';
import {gameConfig} from '../../config';

export class SpiderStartScene extends Phaser.Scene {
    constructor() {
        super(SpiderGameScenes.SpiderStart);
    }

    preload() {
    }

    create() {
        const scene = this;

        addButtonInteractivity(scene);
        addGeneratedButtonSounds(scene);
        testButtonViewInteractivity(scene);

        new BgAssetManager({scene});
        new SoundPlayerFeature({scene, gameConfig});
        new SpiderSettingsDialogManager({scene, gameConfig});
        new SpiderSelectStyleDialogManager({scene});
        new SpiderStartView({scene});
    }
}
