import { assetsViewsAutoAssets } from "../assets-views-assets";
import { assetsViewsTexts } from "./assets-views.text";
import {
  createContainerFromViewData,
  createAssetChild,
  setLeftTop,
} from "../utils";

export const buttonBackData = {
  name: "buttonBack",
  button: true,
  width: 75,
  height: 80,
  children: {
    'icon-back-gold': {
      asset: assetsViewsAutoAssets.iconBackGold,
      x: 0,
      y: 0,
      width: 75,
      height: 80,
    },
  },
};

export function createButtonBack(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const view = createContainerFromViewData(scene, buttonBackData);

  const iconBackGold = createAssetChild(scene, buttonBackData.children['icon-back-gold']);
  setLeftTop(
    iconBackGold,
    buttonBackData.children['icon-back-gold'].x - buttonBackData.width / 2,
    buttonBackData.children['icon-back-gold'].y - buttonBackData.height / 2,
  );
  view.add(iconBackGold);

  return view;
}
