import {SceneEvents} from "../../../../common";
import {themeConfig, type ThemeCardBack} from "../../../../config.themes";
import {GameServiceProvider} from "../../../../services";
import {IGameEvents} from "../../../events";

interface IProps {
    scene: Phaser.Scene;
}

/** Контроллер рубашек: покупка, выбор и синхронизация события с игровыми картами. **/
export class CardBackShopController {
    private readonly events: SceneEvents<IGameEvents>;

    constructor(private readonly props: IProps) {
        this.events = new SceneEvents<IGameEvents>({scene: props.scene});
    }

    destroy(): void {
        this.events.unSubscribeAll();
    }

    selectCardBack(cardBackAssetName: string): void {
        const gameService = GameServiceProvider.get();

        gameService.setPlayerData({
            cardBackAssetName,
        });

        this.events.emit("cardThemeBackChange", {
            backAssetKey: cardBackAssetName,
        });
    }

    buyCardBack(cardBack: ThemeCardBack): boolean {
        const gameService = GameServiceProvider.get();
        const playerData = gameService.getPlayerData();
        const boughtCardBackIds = playerData.boughtCardBackIds;

        if (cardBack.price <= 0 || boughtCardBackIds.indexOf(cardBack.id) >= 0) {
            this.selectCardBack(cardBack.image.name);
            return true;
        }

        if (playerData.gold < cardBack.price) {
            console.warn("not enough gold for card back", cardBack.id);
            return false;
        }

        gameService.setPlayerData({
            /** Покупка и выбранная рубашка сохраняются вместе, чтобы экран сразу открывался в актуальном состоянии. **/
            gold: playerData.gold - cardBack.price,
            boughtCardBackIds: [...boughtCardBackIds, cardBack.id],
            cardBackAssetName: cardBack.image.name,
        });

        this.events.emit("cardThemeBackChange", {
            backAssetKey: cardBack.image.name,
        });

        return true;
    }

    buyCardBackById(cardBackId: string): boolean {
        const cardBack = themeConfig.cardBacks.find((item) => item.id === cardBackId);
        if (cardBack == null) {
            console.warn("unknown card back", cardBackId);
            return false;
        }

        /** Поиск товара остается внутри контроллера рубашек, чтобы flow не знал устройство витрины. **/
        return this.buyCardBack(cardBack);
    }
}
